	@Test
	public void erroneousIfConditionEvaluatesNeitherBranch() {
		AtomicInteger selected = new AtomicInteger();
		QueryValueEvaluationStep branch = bindings -> {
			selected.incrementAndGet();
			return BooleanLiteral.TRUE;
		};
		QueryValueEvaluationStep condition = new QueryValueEvaluationStep.Fail("condition error");
		IfValueEvaluationStep step = new IfValueEvaluationStep(branch, condition, branch);
		assertThrows(ValueExprEvaluationException.class, () -> step.evaluate(EmptyBindingSet.getInstance()));
		assertThat(selected).hasValue(0);
	}

	@Test
	public void logicalStepsShortCircuitAndPreserveIncompatibleErrors() {
		AtomicInteger evaluations = new AtomicInteger();
		QueryValueEvaluationStep error = bindings -> {
			evaluations.incrementAndGet();
			throw new ValueExprEvaluationException("unselected operand");
		};
		QueryValueEvaluationStep truth = bindings -> BooleanLiteral.TRUE;
		QueryValueEvaluationStep falsity = bindings -> BooleanLiteral.FALSE;
		assertThat(new AndValueEvaluationStep(falsity, error).evaluate(EmptyBindingSet.getInstance()))
				.isEqualTo(BooleanLiteral.FALSE);
		assertThat(new OrValueEvaluationStep(truth, error).evaluate(EmptyBindingSet.getInstance()))
				.isEqualTo(BooleanLiteral.TRUE);
		assertThat(evaluations).hasValue(0);
		QueryValueEvaluationStep incompatible = bindings -> SimpleValueFactory.getInstance().createIRI("urn:error");
		assertThrows(ValueExprEvaluationException.class,
				() -> new AndValueEvaluationStep(incompatible, truth).evaluate(EmptyBindingSet.getInstance()));
		assertThrows(ValueExprEvaluationException.class, () -> QueryValueEvaluationStepSupplier
				.prepareAnd(incompatible, truth)
				.evaluate(EmptyBindingSet.getInstance()));
	}

	private static Boolean logicalResult(String operator, int left, int right) {
		if (operator.equals("&&")) {
			return left == 1 || right == 1 ? Boolean.FALSE : left == 2 || right == 2 ? null : Boolean.TRUE;
		}
		return left == 0 || right == 0 ? Boolean.TRUE : left == 2 || right == 2 ? null : Boolean.FALSE;
	}

